/**
 * Reads every public-visibility markdown page in `Neuvetra/neuvetra-kb/wiki/`
 * and emits a typed TypeScript const at `apps/api/src/generated/kb-corpus.ts`.
 *
 * The runtime (`apps/api/src/lib/kb-corpus.ts`) consumes the generated file,
 * not the markdown directly — neuvetra-kb is outside the Site repo, so on
 * Railway the API has no filesystem access to it. The generated file is
 * committed to git; running this script is part of the authoring workflow:
 *
 *   1. Author / edit pages in `Neuvetra/neuvetra-kb/wiki/`.
 *   2. Run `bun run sync-kb` from `Site/apps/api/`.
 *   3. Commit + push the regenerated file along with whatever else changed.
 *
 * Drafts (`visibility: draft`) are skipped. README.md files are skipped.
 */

import { readdir, readFile, writeFile } from "node:fs/promises"
import { join, relative } from "node:path"
import { parse as parseYaml } from "yaml"

interface KbPage {
  /** Stable slug from frontmatter `id`. */
  id: string
  /** Page type — product, plan, feature, etc. */
  type: string
  /** Display title from frontmatter `title`. */
  title: string
  /** Folder path under `wiki/` — used for citation slugs. */
  pathFromWiki: string
  /** Aliases the chatbot should match for this page. */
  aliases: string[]
  /** Product tags. Empty array = brand-level. */
  products: string[]
  /** Markdown body (everything after the closing `---`). */
  body: string
}

const KB_WIKI_DIR = join(import.meta.dir, "..", "..", "..", "..", "neuvetra-kb", "wiki")
const OUTPUT_PATH = join(import.meta.dir, "..", "src", "generated", "kb-corpus.ts")

async function listMarkdownFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true })
  const files: string[] = []
  for (const entry of entries) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) {
      files.push(...(await listMarkdownFiles(full)))
    } else if (
      entry.isFile() &&
      entry.name.endsWith(".md") &&
      entry.name !== "README.md" &&
      entry.name !== "index.md" &&
      entry.name !== "log.md"
    ) {
      files.push(full)
    }
  }
  return files
}

function splitFrontmatter(content: string): { fm: Record<string, unknown>; body: string } {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/)
  if (!match) return { fm: {}, body: content }
  const fm = (parseYaml(match[1]!) ?? {}) as Record<string, unknown>
  return { fm, body: (match[2] ?? "").trim() }
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  return value.filter((v): v is string => typeof v === "string")
}

async function buildCorpus(): Promise<KbPage[]> {
  const files = await listMarkdownFiles(KB_WIKI_DIR)
  const pages: KbPage[] = []

  for (const file of files) {
    const raw = await readFile(file, "utf-8")
    const { fm, body } = splitFrontmatter(raw)

    const visibility = typeof fm.visibility === "string" ? fm.visibility : "public"
    if (visibility !== "public") continue

    const id = typeof fm.id === "string" ? fm.id : null
    const type = typeof fm.type === "string" ? fm.type : null
    const title = typeof fm.title === "string" ? fm.title : null
    if (!id || !type || !title) {
      console.warn(`[sync-kb-corpus] skipping ${file} — missing id/type/title`)
      continue
    }

    const pathFromWiki = relative(KB_WIKI_DIR, file).replace(/\\/g, "/").replace(/\.md$/, "")

    pages.push({
      id,
      type,
      title,
      pathFromWiki,
      aliases: asStringArray(fm.aliases),
      products: asStringArray(fm.products),
      body,
    })
  }

  pages.sort((a, b) => a.pathFromWiki.localeCompare(b.pathFromWiki))
  return pages
}

function emit(pages: KbPage[]): string {
  const generatedAt = new Date().toISOString()
  return `// AUTO-GENERATED by apps/api/scripts/sync-kb-corpus.ts.
// Do not edit by hand. Re-run \`bun run sync-kb\` from apps/api/ after
// editing pages in Neuvetra/neuvetra-kb/wiki/.
//
// Source: Neuvetra/neuvetra-kb/wiki/
// Pages: ${pages.length} public
// Generated: ${generatedAt}

export interface KbPage {
  /** Stable slug from frontmatter \`id\`. */
  id: string
  /** Page type — product, plan, feature, etc. */
  type: string
  /** Display title. */
  title: string
  /** Folder path under wiki/ (without the .md extension). Used for citation slugs. */
  pathFromWiki: string
  /** Aliases the chatbot should match for this page. */
  aliases: readonly string[]
  /** Product tags. Empty array = brand-level. */
  products: readonly string[]
  /** Markdown body (everything after the frontmatter). */
  body: string
}

export const KB_PAGES: readonly KbPage[] = ${JSON.stringify(pages, null, 2)} as const
`
}

async function main() {
  const pages = await buildCorpus()
  await writeFile(OUTPUT_PATH, emit(pages), "utf-8")
  console.log(
    `[sync-kb-corpus] wrote ${pages.length} pages → ${relative(process.cwd(), OUTPUT_PATH)}`,
  )
  for (const p of pages) {
    console.log(`  · ${p.pathFromWiki} (${p.type}, ${p.body.length} chars)`)
  }
}

main().catch((err) => {
  console.error("[sync-kb-corpus] failed:", err)
  process.exit(1)
})
